s='M N _ O J K M _ Q O J K _ N Q _ J K M N Q O _ K M N'.split()
opts={'A':'QMNJO','B':'QNJMO','C':'QNMOJ','D':'QNMJO'}
def fits(f):
  it=iter(f); t=[next(it) if c=='_' else c for c in s]
  return all(t[i]=='MNQOJK'[i%6] for i in range(len(t)))
assert [k for k,v in opts.items() if fits(v)]==['C']

